-- Database: u773410069_materiadb
-- (Select u773410069_materiadb in phpMyAdmin before importing)

-- Products Table
CREATE TABLE IF NOT EXISTS products (
    id VARCHAR(50) PRIMARY KEY,
    slug VARCHAR(255) NOT NULL,
    name_en VARCHAR(255) NOT NULL,
    name_ar VARCHAR(255) NOT NULL,
    code VARCHAR(50) NOT NULL,
    description_en TEXT,
    description_ar TEXT,
    thickness VARCHAR(50),
    width VARCHAR(50),
    material_type_en VARCHAR(255),
    material_type_ar VARCHAR(255),
    texture_en VARCHAR(255),
    texture_ar VARCHAR(255),
    backing_en VARCHAR(255),
    backing_ar VARCHAR(255),
    finish_en VARCHAR(255),
    finish_ar VARCHAR(255),
    water_resistance_en VARCHAR(255),
    water_resistance_ar VARCHAR(255),
    fire_resistance_en VARCHAR(255),
    fire_resistance_ar VARCHAR(255),
    softness_level_en VARCHAR(255),
    softness_level_ar VARCHAR(255),
    image MEDIUMTEXT,
    is_new BOOLEAN DEFAULT FALSE,
    is_best_seller BOOLEAN DEFAULT FALSE,
    categories TEXT, -- JSON array
    colors TEXT, -- JSON array
    applications TEXT, -- JSON array
    gallery_images MEDIUMTEXT, -- JSON array
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Translations Table (Key-Value)
CREATE TABLE IF NOT EXISTS translations (
    lang VARCHAR(5) NOT NULL,
    t_key VARCHAR(255) NOT NULL,
    t_value TEXT NOT NULL,
    PRIMARY KEY (lang, t_key)
);

-- Site Settings
CREATE TABLE IF NOT EXISTS site_settings (
    s_key VARCHAR(255) PRIMARY KEY,
    s_value TEXT NOT NULL
);


