  'خامة FORMULA B43',
  'B43',
  'Favini release paper texture FORMULA B43 from the Medium & Large Grains collection. Crafted using Coated / Extruded process for PVC, PU & PVC, PU synthetic leather. Finish: PVC 1, BSC 100, BHT, BNS. Deep, pronounced natural grain texture engineered for premium upholstered furniture, automotive upholstery, and luxury leather goods.',
